// Page/cut screen (page 17): visible cut list, toolbar and shortcuts. The popup menu stays behind "더보기".
bool storyAction(const std::function<bool()>& change){if(promptComposing)return false;if(engine->locked(store->active))throw std::runtime_error("생성·예약 작업을 마친 뒤 페이지나 컷을 바꿔 주세요.");save();if(!change())return false;afterStoryChange();return true;}
bool storyConfirm(const wchar_t* text,const wchar_t* title){return MessageBoxW(hwnd,text,title,MB_YESNO|MB_ICONQUESTION)==IDYES;}
void storyDelete(bool deletePage){storyAction([this,deletePage]{if(!storyConfirm(L"선택한 항목을 삭제할까요?\n이미지 파일은 보존하며 최근 삭제 10개는 되돌릴 수 있습니다.",L"페이지·컷 삭제"))return false;store->deleteBoard(deletePage);return true;});}
void storyRename(bool renamePage){storyAction([this,renamePage]{auto& board=store->current()["storyboard"];auto name=inputBox(hwnd,renamePage?L"페이지 이름":L"컷 이름",wide(str(renamePage?boardPage(board,str(board,"active_page")):activeBoardPanel(board),"name")));if(name.empty())return false;store->renameBoard(renamePage,utf8(name));return true;});}
void storyNewPage(){storyAction([this]{auto name=inputBox(hwnd,L"새 페이지 이름");if(name.empty())return false;store->addBoardPage(utf8(name));return true;});}
void storyStart(){storyAction([this]{if(!storyConfirm(L"현재 작업을 1페이지·1컷으로 유지하며 시작할까요?\n기존 프로젝트 파일을 백업합니다.",L"페이지·컷"))return false;store->enableStoryboard();return true;});}
void storyRestoreFile(){storyAction([this]{auto file=fileDialog(hwnd,false,L"페이지·컷 백업\0*.json\0\0");if(file.empty())return false;store->restoreStoryboardRecord(readJson(file));return true;});}
void storyMove(int delta){storyAction([this,delta]{store->moveBoardPanel(delta);return true;});}
void storySelect(const std::string& pageId,const std::string& panelId){storyAction([this,pageId,panelId]{store->selectBoard(pageId,panelId);return true;});}
